      "XH-8850 Medikal Su Arıtma Sistemi; ISO EP y, 93/42/EEC, ISO 13485 ve ISO 61010 standartlarında saatte 5000 Litre saf su üretmektedir. Modüler ve değiştirilebilir paket içerikleri, Yüksek performans ve rakipsiz konfigürasyon seçenekleri sunan Ultra XH-8850 Medikal Su Arıtma Sistemi; teknolojik, analitik, metodolojik, üretim standartları, garanti koşulları ve servis ağı bakımından ulaşabileceğiniz en iyi saf su cihazıdır."
