      "ED-9810 Elektrodeiyonizasyon Cihazı; ISO, ASTM, EP y, EU, WQA, EEC endüstri ve medikal üretim standartlarında saatte 60 litre akredite ultra saf su üretmektedir. Modüler ve değiştirilebilir paket içerikleri, Yüksek performans ve rakipsiz konfigürasyon seçenekleri sunan Ultra ED-9810 Elektrodeiyonizasyon Cihazı; teknolojik, analitik, metodolojik, üretim standartları, garanti koşulları ve servis ağı bakımından ulaşabileceğiniz en iyi elektrodeiyonizasyon cihazıdır."
